// Valida e prepara payload para o Asaas
const body = $input.item.json.body || $input.item.json;

const required = ['payment_id', 'client_cpf_cnpj', 'value', 'due_date'];
for (const field of required) {
  if (!body[field]) throw new Error(`Campo obrigatório ausente: ${field}`);
}

// Formata CPF/CNPJ (remove formatação)
const cpfCnpj = body.client_cpf_cnpj.replace(/\D/g, '');

return [{ json: {
  payment_id: body.payment_id,
  organization_id: body.organization_id,
  client_name: body.client_name || 'Cliente',
  client_email: body.client_email || '',
  cpf_cnpj: cpfCnpj,
  value: Number(body.value),
  due_date: body.due_date,
  description: body.description || 'Cobrança PIX',
} }];

// Determina se precisa criar cliente ou usa o existente
const asaasResponse = $input.item.json;
const input = $('Validar e Preparar').item.json;

const existingCustomer = asaasResponse.data?.[0];

if (existingCustomer) {
  return [{ json: { ...input, asaas_customer_id: existingCustomer.id, create_customer: false } }];
} else {
  return [{ json: { ...input, asaas_customer_id: null, create_customer: true } }];
}

// Monta payload para criação da cobrança PIX
const input = $('Verificar Cliente').item.json;
const createdCustomer = $input.item.json;

const customerId = createdCustomer?.id || input.asaas_customer_id;

return [{ json: {
  payment_id: input.payment_id,
  organization_id: input.organization_id,
  customer: customerId,
  billingType: 'PIX',
  value: input.value,
  dueDate: input.due_date,
  description: input.description,
  externalReference: input.payment_id,
} }];

// Salva asaas_id e dados do PIX no pagamento do Maestr.ia
const charge = $('Criar Cobrança PIX no Asaas').item.json;
const qrcode = $input.item.json;
const prep = $('Preparar Cobrança PIX').item.json;

return [{ json: {
  payment_id: prep.payment_id,
  organization_id: prep.organization_id,
  asaas_id: charge.id,
  pix_copy_paste: qrcode.payload,
  pix_qr_code_image: qrcode.encodedImage ? `data:image/png;base64,${qrcode.encodedImage}` : null,
  pix_expiration: qrcode.expirationDate,
  due_date: charge.dueDate,
  value: charge.value,
} }];
